/**
 * Accuracy A/B harness — injection corpus, per-arm rendering, breakpoint-resume.
 *
 * Consumes docs/internal/accuracy-corpus.jsonl (generated by
 * curate-accuracy.ts): each item carries RAW SessionEntry[] and per-arm
 * expectations derived from what that arm's rendered delta actually shows.
 *
 * For each (item, arm): render the raw entries with the PRODUCTION renderer
 * (`renderAdvisorDelta` + includeReasoning=arm==="old"), prompt one fresh
 * nested advisor session, and score the verdict against the per-arm
 * expectation:
 *   - expectation finding (signature visible to this arm):
 *       hit = note contains the signature term; miss = otherwise
 *   - expectation silence (signature NOT visible to this arm):
 *       silence-correct = no note; false-positive = note delivered
 * So the corpus is arm-fair: each arm is scored only on what its own rendered
 * window shows. The four injection zones are balanced (no pro-new/pro-old
 * bias): reasoning (old-only signal), toolresult (both), tail (new-only
 * retention benefit), clean (silence control).
 *
 * Breakpoint resume: every result is appended to docs/internal/accuracy-results.jsonl
 * immediately after its review; on re-run, completed (itemId, arm) pairs are
 * skipped, so an interrupted run resumes without re-reviewing or re-spending.
 *
 * Run: `bun scripts/f9-experiment/run-accuracy.ts [--limit-items N]`
 */
import { appendFile, mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

import {
	createAgentSession,
	DefaultResourceLoader,
	getAgentDir,
	ModelRegistry,
	ModelRuntime,
	SessionManager,
	SettingsManager,
	type AgentSession,
} from "@earendil-works/pi-coding-agent";
import type { Model } from "@earendil-works/pi-ai";

import { createAdviseTool, type AdviceCollector } from "../../src/advice.js";
import { loadAdvisorConfiguration } from "../../src/configuration.js";
import { DEFAULT_ADVISOR_CONFIG } from "../../src/config.js";
import { buildAdvisorSystemPrompt } from "../../src/runtime.js";
import { renderAdvisorDelta } from "../../src/transcript.js";
import {
	f9HarnessHash,
	gitHeadCommit,
	identityBaseMatches,
	sha256Head16,
	type ExperimentIdentityBase,
} from "./experiment-identity.js";
import {
	lastAssistantUsage,
	loadPersistedJsonl,
	registerUserProviderExtensions,
} from "./harness.js";

const REVIEW_TOKEN_CEILING = 1_000_000;
const COST_CEILING_USD = 25;
const CORPUS_PATH = join("docs", "internal", "accuracy-corpus.jsonl");
const RESULTS_PATH = join("docs", "internal", "accuracy-results.jsonl");

type Arm = "old" | "new";
type Verdict = "hit" | "miss" | "false-positive" | "silence-correct" | "run-error";

interface AccuracyItem {
	id: string;
	sourceCut: string;
	variant: "clean" | "reasoning" | "toolresult" | "tail";
	budgetTokens: number;
	entries: unknown[];
	expectation: {
		old: { kind: "silence" } | { kind: "finding"; terms: string[] };
		new: { kind: "silence" } | { kind: "finding"; terms: string[] };
	};
	visibleIn: { old: boolean; new: boolean };
}

interface AccuracyRow {
	itemId: string;
	arm: Arm;
	variant: AccuracyItem["variant"];
	expected: "silence" | "finding";
	visible: boolean;
	verdict: Verdict;
	note?: string;
	severity?: string;
	stopReason: string;
	tokens: number;
	inputTokens: number;
	cachedTokens: number;
	costUsd: number;
	renderedBytes: number;
	responseModel?: string;
	/** Experiment identity — a persisted row is only eligible for resume when it
	 * matches the current corpus/model/prompt/harness. Optional: rows persisted
	 * before identity tracking have no field and are discarded on resume. */
	experiment?: {
		datasetHash: string;
		model: string;
		budgetTokens: number;
		promptHash: string;
		protocol: string;
		sourceCommit: string;
		harnessHash: string;
	};
}

const ACCURACY_PROTOCOL = "accuracy-experiment-v1";

interface AccuracyExperimentIdentity extends ExperimentIdentityBase {
	budgetTokens: number;
}

function buildAccuracyIdentity(
	model: string,
	prompt: string,
	items: readonly AccuracyItem[],
): AccuracyExperimentIdentity {
	// Hash the semantic corpus shape (ids, per-arm expectations, visibility and
	// rendered entry content) so a regenerated or relabeled corpus invalidates
	// previously persisted results.
	const datasetHash = sha256Head16(
		JSON.stringify(
			items.map((item) => ({
				id: item.id,
				variant: item.variant,
				budgetTokens: item.budgetTokens,
				expectation: item.expectation,
				visibleIn: item.visibleIn,
				entries: item.entries,
			})),
		),
	);
	return {
		datasetHash,
		model,
		budgetTokens: items[0]?.budgetTokens ?? 0,
		promptHash: sha256Head16(prompt),
		protocol: ACCURACY_PROTOCOL,
		sourceCommit: gitHeadCommit(),
		harnessHash: f9HarnessHash(import.meta.url),
	};
}

function identityMatches(row: AccuracyRow, identity: AccuracyExperimentIdentity): boolean {
	return (
		identityBaseMatches(row.experiment, identity) &&
		row.experiment?.budgetTokens === identity.budgetTokens
	);
}

async function loadCorpus(): Promise<AccuracyItem[]> {
	try {
		const raw = await readFile(CORPUS_PATH, "utf8");
		// SAFETY: accuracy-corpus.jsonl rows are written by curate-accuracy.ts
		// with a fixed AccuracyItem schema; malformed lines surface on access.
		return raw
			.split("\n")
			.filter((line) => line.trim().length > 0)
			.map((line) => JSON.parse(line) as AccuracyItem);
	} catch (error) {
		console.error(
			`[acc] cannot read ${CORPUS_PATH}: ${error instanceof Error ? error.message : String(error)}`,
		);
		return [];
	}
}

async function loadPersistedResults(): Promise<AccuracyRow[]> {
	// Fail closed on corruption: degrading to [] would re-run (and re-bill) every
	// already-completed (item, arm) pair of live reviews.
	return loadPersistedJsonl<AccuracyRow>(RESULTS_PATH, "[acc]");
}

function verdictFor(
	expected: AccuracyItem["expectation"][Arm],
	visible: boolean,
	note: string | undefined,
	terms: readonly string[],
): Verdict {
	if (expected.kind === "silence" || !visible) {
		return note === undefined ? "silence-correct" : "false-positive";
	}
	if (note === undefined) return "miss";
	const normalized = note.toLocaleLowerCase("en-US");
	return terms.some((term) => normalized.includes(term)) ? "hit" : "miss";
}

interface AdviseView {
	note?: string;
	severity?: string;
}

function sessionAdviseView(session: AgentSession): AdviseView {
	let last: AdviseView = {};
	for (const message of session.messages) {
		if (message.role !== "assistant") continue;
		// AgentMessage assistant content is a non-optional content-block array.
		for (const part of message.content) {
			if (part.type !== "toolCall" || part.name !== "advise") continue;
			// SAFETY: advise toolCall arguments are JSON-schema-constrained by the
			// advise tool contract; unknown fields are ignored downstream.
			const args = part.arguments as {
				note?: string;
				severity?: string;
				outcome?: { advised?: boolean };
			};
			if (args.outcome?.advised === false) continue;
			if (args.note !== undefined) {
				last = { note: args.note };
				if (args.severity !== undefined) last.severity = args.severity;
			}
		}
	}
	return last;
}

async function runOneReview(options: {
	cwd: string;
	agentDir: string;
	modelRuntime: ModelRuntime;
	model: Model<string>;
	arm: Arm;
	prompt: string;
	item: AccuracyItem;
	config: typeof DEFAULT_ADVISOR_CONFIG;
}): Promise<AccuracyRow> {
	const { config } = options;
	const collector: AdviceCollector = {
		validCalls: 0,
		suppressedCalls: 0,
		memoryPolicySuppressedCalls: 0,
		memoryLimitSuppressedCalls: 0,
	};
	const settingsManager = SettingsManager.inMemory({
		compaction: { enabled: false },
		retry: { enabled: false },
	});
	const resourceLoader = new DefaultResourceLoader({
		cwd: options.cwd,
		agentDir: options.agentDir,
		settingsManager,
		noExtensions: true,
		noSkills: true,
		noPromptTemplates: true,
		noThemes: true,
		noContextFiles: true,
		systemPromptOverride: () => options.prompt,
		appendSystemPromptOverride: () => [],
	});
	await resourceLoader.reload();
	const sessionManager = SessionManager.inMemory(options.cwd);
	const { session } = await createAgentSession({
		cwd: options.cwd,
		agentDir: options.agentDir,
		modelRuntime: options.modelRuntime,
		model: options.model,
		thinkingLevel: "off",
		resourceLoader,
		sessionManager,
		settingsManager,
		customTools: [createAdviseTool(config, collector)],
		tools: ["advise"],
	});
	const expected = options.item.expectation[options.arm];
	const visible = options.item.visibleIn[options.arm];
	const terms = expected.kind === "finding" ? expected.terms : [];

	const includeReasoning = options.arm === "old";
	const rendered = renderAdvisorDelta(
		// SAFETY: dataset entries are SessionEntry objects serialized verbatim by
		// collect-corpus.ts; renderAdvisorDelta reads them defensively.
		options.item.entries as Parameters<typeof renderAdvisorDelta>[0],
		options.item.budgetTokens,
		{ includeReasoning },
	);
	const delta = rendered.text;
	// SAFETY: rowBase fields mirror the AccuracyRow schema written to
	// results.jsonl by this script's run stages.
	const rowBase = {
		itemId: options.item.id,
		arm: options.arm,
		variant: options.item.variant,
		expected: expected.kind,
		visible,
	} as AccuracyRow;
	try {
		await session.prompt(`<advisor-update>\n${delta}\n</advisor-update>`, {
			expandPromptTemplates: false,
			source: "extension",
		});
	} catch (error) {
		rowBase.verdict = "run-error";
		rowBase.stopReason = "thrown";
		rowBase.tokens = 0;
		rowBase.inputTokens = 0;
		rowBase.cachedTokens = 0;
		rowBase.costUsd = 0;
		rowBase.renderedBytes = Buffer.byteLength(delta, "utf8");
		console.error(
			`  -> ${options.item.id} ${options.arm} run error: ${error instanceof Error ? error.message : String(error)}`,
		);
		return rowBase;
	}
	const usage = lastAssistantUsage(session);
	const adviseView = sessionAdviseView(session);
	const row: AccuracyRow = {
		...rowBase,
		verdict: verdictFor(expected, visible, adviseView.note, terms),
		stopReason:
			// SAFETY: the last message is an AgentMessage; stopReason is read as an
			// untrusted string with an "unknown" fallback, nothing else is assumed.
			(session.messages.at(-1) as { stopReason?: string } | undefined)?.stopReason ?? "unknown",
		tokens: usage.tokens,
		inputTokens: usage.inputTokens,
		cachedTokens: usage.cachedTokens,
		costUsd: usage.costUsd,
		renderedBytes: Buffer.byteLength(delta, "utf8"),
	};
	if (adviseView.note !== undefined) row.note = adviseView.note;
	if (adviseView.severity !== undefined) row.severity = adviseView.severity;
	if (usage.responseModel !== undefined) row.responseModel = usage.responseModel;
	session.dispose();
	console.log(
		`  -> ${options.item.id} ${options.arm} verdict=${row.verdict} (${String(usage.tokens)} tok, in ${String(usage.inputTokens)}, cached ${String(usage.cachedTokens)})${row.note === undefined ? "" : `: ${row.note.slice(0, 70)}`}`,
	);
	return row;
}

async function writeEvaluation(options: {
	modelReference: string;
	responseModels: Set<string>;
	rows: AccuracyRow[];
	stoppedEarly: boolean;
	reason?: string;
}): Promise<string> {
	const { rows } = options;
	const perArm = new Map<
		Arm,
		Map<
			string,
			{
				n: number;
				hit: number;
				miss: number;
				fp: number;
				silence: number;
				tokens: number;
				cached: number;
				input: number;
			}
		>
	>();
	for (const arm of ["old", "new"] as const) {
		perArm.set(arm, new Map());
	}
	for (const r of rows) {
		if (r.verdict === "run-error") continue;
		const armMap = perArm.get(r.arm);
		if (armMap === undefined) continue;
		const bucket = armMap.get(r.variant) ?? {
			n: 0,
			hit: 0,
			miss: 0,
			fp: 0,
			silence: 0,
			tokens: 0,
			cached: 0,
			input: 0,
		};
		bucket.n += 1;
		if (r.verdict === "hit") bucket.hit += 1;
		if (r.verdict === "miss") bucket.miss += 1;
		if (r.verdict === "false-positive") bucket.fp += 1;
		if (r.verdict === "silence-correct") bucket.silence += 1;
		bucket.tokens += r.tokens;
		bucket.cached += r.cachedTokens;
		bucket.input += r.inputTokens;
		armMap.set(r.variant, bucket);
	}

	const sections: string[] = [];
	for (const arm of ["old", "new"] as const) {
		const map = perArm.get(arm);
		if (map === undefined) continue;
		const lines = [...map.entries()]
			.map(([variant, b]) => {
				const total = b.n === 0 ? 0 : b.n;
				const hitRate = total === 0 ? 0 : (b.hit / total) * 100;
				const fpRate = total === 0 ? 0 : (b.fp / total) * 100;
				return `| ${variant} | ${String(total)} | ${String(b.hit)} | ${String(b.miss)} | ${String(b.fp)} | ${String(b.silence)} | ${hitRate.toFixed(0)}% | ${fpRate.toFixed(0)}% | ${String(b.tokens)} | ${String(b.cached)} |`;
			})
			.join("\n");
		sections.push(
			`### arm=${arm}\n\n| Variant | n | hit | miss | FP | silence-correct | hit-rate | FP-rate | Σtokens | Σcached |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\n${lines}`,
		);
	}

	const detail = rows
		.map((r) => {
			const share =
				r.inputTokens + r.cachedTokens === 0
					? 0
					: (r.cachedTokens / (r.inputTokens + r.cachedTokens)) * 100;
			return `| ${r.itemId} | ${r.arm} | ${r.variant} | ${r.expected}/${r.visible ? "shown" : "hidden"} | ${r.verdict} | ${String(r.tokens)} | ${String(r.cachedTokens)} (${share.toFixed(0)}%) | ${(r.note ?? "(none)").replaceAll("\n", " ").slice(0, 70).replaceAll("|", "\\|")} |`;
		})
		.join("\n");

	const note = `# Advisor 准确率对比（注入用例，per-arm 渲染）— deepseek-v4-flash

Status: ${options.stoppedEarly ? `stopped early: ${options.reason ?? "budget ceiling reached"}` : "completed"}.
语料: \`docs/internal/accuracy-corpus.jsonl\`（36 条 = 9 ctx cut × 4 variant）。每个注入用例带
唯一可验证签名 \`INJECTED_DEFECT_audit_v7_downgrade_14_203_rows_no_backup\`；**期望按各 arm
实际可见性计算**（签名在 arm 渲染窗口内 ⇒ finding，否则 silence），因此不偏向任何一方。
渲染: 每 arm 独立用 production \`renderAdvisorDelta\`（old=includeReasoning:true, new=false），
修复"两 arm 喂同一预渲染文本"的旧缺陷。

## 模型与参数
- 配置模型: \`${options.modelReference}\`（WATCHDOG.yml）；response models: ${[...options.responseModels].join(", ") || "(none)"}
- budget: maxUpdateTokens 20,000 → 80,000 字节；软顶 1e6 tokens / $25

## 按 arm 分 variant 汇总

${sections.join("\n\n")}

### 全部明细

| Item | Arm | Variant | Expected/Visibility | Verdict | Tokens | Cached (share) | Note |
| --- | --- | --- | --- | --- | --- | --- | --- |
${detail}

## Reading

- \`reasoning\`: 签名只在 thinking 块（old 可见；new 剥除）。old 命中 vs new 保持沉默 = reasoning
  承载检测信号（no-reasoning 有召回损失）；old 也沉默 = 该信号不值得检测。
- \`toolresult\`: 签名工具结果体，两 arm 都可见。两方都应命中（确认注入可检测、基线一致）。
- \`tail\`: 签名落在 old 截断区、new 保留区。new 命中 vs old 看不到 = no-reasoning 多保留历史
  带来召回增益。
- \`clean\`: 无注入，期望安静。任一 arm 出实质 note = false-positive（噪声率对比）。
- 单次 run、n=9/variant/arm，方差主导；差值为信号而非定论。
`;

	const path = join("docs", "internal", "accuracy-evaluation.md");
	await mkdir(dirname(path), { recursive: true });
	await writeFile(path, note, "utf8");
	return path;
}

import { dirname } from "node:path";

async function main(): Promise<void> {
	const args = process.argv.slice(2);
	const limitRaw = args.find((_v, index) => args[index - 1] === "--limit-items");
	const limitItems = limitRaw === undefined ? undefined : Number.parseInt(limitRaw, 10);
	const corpus = await loadCorpus();
	if (corpus.length === 0) {
		console.error(`[acc] corpus empty at ${CORPUS_PATH}`);
		process.exitCode = 1;
		return;
	}
	let items = corpus;
	if (limitItems !== undefined && Number.isFinite(limitItems) && limitItems > 0) {
		items = corpus.slice(0, limitItems);
	}
	const persisted = await loadPersistedResults();

	const agentDir = getAgentDir();
	const cwd = process.cwd();
	const loaded = await loadAdvisorConfiguration({
		agentDir,
		cwd,
		projectTrusted: false,
		fallbackUserConfig: DEFAULT_ADVISOR_CONFIG,
	});
	const modelReference = loaded.effectiveConfig.model;
	if (modelReference === undefined) {
		console.error("[acc] requires a configured Advisor model in the User WATCHDOG configuration.");
		process.exitCode = 1;
		return;
	}
	const separator = modelReference.indexOf("/");
	const providerId = separator < 0 ? modelReference : modelReference.slice(0, separator);
	const modelId = separator < 0 ? modelReference : modelReference.slice(separator + 1);

	const modelRuntime = await ModelRuntime.create({
		authPath: join(agentDir, "auth.json"),
		modelsPath: join(agentDir, "models.json"),
		allowModelNetwork: true,
	});
	const registry = new ModelRegistry(modelRuntime);
	let available = registry.getAvailable();
	if (!available.some((model) => `${model.provider}/${model.id}` === modelReference)) {
		const loadedExtensions = await registerUserProviderExtensions(
			agentDir,
			providerId,
			modelRuntime,
			"acc",
		);
		if (loadedExtensions.length > 0) {
			console.log(`[acc] loaded provider extension: ${loadedExtensions.join(", ")}`);
			await registry.refresh();
			available = registry.getAvailable();
		}
	}
	if (!available.some((model) => `${model.provider}/${model.id}` === modelReference)) {
		console.error(`[acc] could not resolve an authenticated model for ${modelReference}.`);
		process.exitCode = 1;
		return;
	}
	const model = modelRuntime.getModel(providerId, modelId);
	if (model === undefined) {
		console.error(`[acc] could not find model ${modelReference}.`);
		process.exitCode = 1;
		return;
	}
	// SAFETY: loaded.effectiveConfig is the Advisor user config shape; the cast
	// pins the merged result back to the canonical config contract.
	const configForRun = { ...loaded.effectiveConfig } as typeof DEFAULT_ADVISOR_CONFIG;
	const prompt = buildAdvisorSystemPrompt(configForRun, "");
	// Resume eligibility: a persisted row is only reused when its experiment
	// identity matches the current corpus/model/prompt/harness — otherwise a
	// changed corpus or rendering path would silently mix unrelated results.
	const experiment = buildAccuracyIdentity(modelReference, prompt, items);
	const eligiblePersisted = persisted.filter((row) => identityMatches(row, experiment));
	if (persisted.length !== eligiblePersisted.length) {
		console.log(
			`[acc] identity mismatch: discarding ${String(persisted.length - eligiblePersisted.length)} persisted results (corpus/model/prompt/harness changed)`,
		);
	}
	const done = new Set(eligiblePersisted.map((r) => `${r.itemId}:${r.arm}`));
	console.log(
		`[acc] corpus ${String(items.length)} items; ${String(eligiblePersisted.length)} already recorded`,
	);
	console.log(`[acc] model ${modelReference}`);

	const rows: AccuracyRow[] = [...eligiblePersisted];
	const responseModels = new Set<string>(
		eligiblePersisted.flatMap((r) => (r.responseModel === undefined ? [] : [r.responseModel])),
	);
	// Per-invocation budget: the ceiling bounds THIS run's spend, not the
	// accumulated corpus. Breakpoint resume skips recorded pairs and starts with
	// a fresh token budget, so each continuation adds a full slice of reviews.
	let totalTokens = 0;
	let totalCost = 0;
	let stoppedEarly = false;
	let stopReason: string | undefined;

	for (const item of items) {
		for (const arm of ["old", "new"] as const) {
			if (done.has(`${item.id}:${arm}`)) {
				console.log(`[acc] ${item.id} ${arm} (already recorded)`);
				continue;
			}
			console.log(`[acc] === ${item.id} ${arm} ===`);
			const row = await runOneReview({
				cwd,
				agentDir,
				modelRuntime,
				// SAFETY: `model` is the runtime-resolved model instance for this run.
				model: model as Model<string>,
				arm,
				prompt,
				item,
				config: configForRun,
			});
			row.experiment = experiment;
			await appendFile(RESULTS_PATH, `${JSON.stringify(row)}\n`, "utf8");
			rows.push(row);
			totalTokens += row.tokens;
			totalCost += row.costUsd;
			if (row.responseModel !== undefined) responseModels.add(row.responseModel);
			if (totalTokens >= REVIEW_TOKEN_CEILING || totalCost >= COST_CEILING_USD) {
				stoppedEarly = true;
				stopReason = `budget ceiling reached at ${String(totalTokens)} tokens / $${totalCost.toFixed(4)}`;
				break;
			}
		}
		if (stoppedEarly) break;
	}
	const evalOptions: Parameters<typeof writeEvaluation>[0] = {
		modelReference,
		responseModels,
		rows,
		stoppedEarly,
	};
	if (stopReason !== undefined) evalOptions.reason = stopReason;
	const evalPath = await writeEvaluation(evalOptions);
	console.log("");
	for (const arm of ["old", "new"] as const) {
		const sub = rows.filter((r) => r.arm === arm && r.verdict !== "run-error");
		if (sub.length === 0) continue;
		const hit = sub.filter((r) => r.verdict === "hit").length;
		const miss = sub.filter((r) => r.verdict === "miss").length;
		const fp = sub.filter((r) => r.verdict === "false-positive").length;
		const sil = sub.filter((r) => r.verdict === "silence-correct").length;
		const tok = sub.reduce((s, r) => s + r.tokens, 0);
		console.log(
			`[acc] ${arm}: n=${String(sub.length)} hit=${String(hit)} miss=${String(miss)} fp=${String(fp)} silence=${String(sil)} Σtok=${String(tok)}`,
		);
	}
	console.log(`[acc] evaluation note written to ${evalPath}`);
	if (stoppedEarly) console.log(`[acc] ${stopReason ?? "stopped early"}`);
}

await main();
